<script setup lang="ts">
import {Head,Link,useForm} from '@inertiajs/vue3';import Workspace from '@/Layouts/Workspace.vue';import {computed,ref} from 'vue';
const props=defineProps<{product:any;workspace:any;module:string;definition:any;record:any;events:any[];messages:any[];role:string}>();
const base=`/app/${props.workspace.slug}/${props.module}/${props.record.id}`;const action=ref('');
const actions=computed(()=>({workflows:['publish','run'],journal_entries:['post'],shipments:['transition','assign'],restaurant_branches:['order'],orders:['transition'],conversations:['reply','note','handoff','close','reopen'],knowledge_articles:['publish']} as Record<string,string[]>)[props.module]||[]);
const form=useForm<Record<string,any>>({idempotency_key:crypto.randomUUID(),body:'',status:'',recipient:'',trip_id:'',items:'[{"product_id":1,"quantity":1}]'});
function submit(){form.transform(data=>{const result={...data};if(action.value==='order'){try{result.items=JSON.parse(data.items);}catch{form.setError('items','Enter a valid JSON array.');throw new Error('Invalid items');}}return result;}).post(`${base}/${action.value}`,{onSuccess:()=>{form.idempotency_key=crypto.randomUUID();form.body='';}});}
</script><template><Head :title="record.name||definition.label"/><Workspace :product="product" :workspace="workspace"><Link :href="`/app/${workspace.slug}/${module}`" class="text-link">← {{definition.label}}</Link><h1>{{record.name||definition.label+' #'+record.id}}</h1><div class="detail-grid"><section class="panel"><h2>Details</h2><dl><template v-for="(type,key) in definition.fields" :key="key"><dt>{{String(key).replaceAll('_',' ')}}</dt><dd><pre v-if="type==='json'">{{JSON.stringify(typeof record[key]==='string'?JSON.parse(record[key]):record[key],null,2)}}</pre><span v-else>{{record[key]}}</span></dd></template></dl></section><form v-if="actions.length && role!=='viewer'" class="panel form-panel" @submit.prevent="submit"><h2>Actions</h2><label>Action<select v-model="action" required><option value="" disabled>Select action</option><option v-for="a in actions" :value="a">{{a}}</option></select></label><label v-if="action==='transition'">Next status<input v-model="form.status" required placeholder="e.g. confirmed"/></label><label v-if="action==='transition'&&module==='shipments'">Recipient (required for delivery)<input v-model="form.recipient"/></label><label v-if="action==='assign'">Trip ID<input v-model="form.trip_id" type="number" required min="1"/></label><label v-if="action==='reply'||action==='note'">Message<textarea v-model="form.body" required rows="5"/></label><label v-if="action==='order'">Items (product ID and quantity)<textarea v-model="form.items" required rows="5"/></label><p v-if="action==='order'" class="muted">Cash order. Prices are calculated from this branch's menu. Payment stays unpaid.</p><p v-for="error in form.errors" class="error">{{error}}</p><button :disabled="!action||form.processing">Apply action</button></form></div><section v-if="module==='conversations'" class="panel"><h2>Conversation</h2><p v-if="!messages.length" class="muted">No messages yet.</p><article class="message" v-for="message in messages" :key="message.id"><span class="badge">{{message.kind}}</span><p class="whitespace-pre-wrap">{{message.body}}</p><small>{{message.created_at}}</small></article></section><section class="panel"><h2>History</h2><div class="activity" v-for="event in events" :key="event.id"><strong>{{event.event_type}}</strong><time>{{event.created_at}}</time></div></section></Workspace></template>
